export async function sumStorageBytes(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({
      value: sql<number | null>`sum(${attachments.sizeBytes})`,
    })
    .from(attachments)
    .where(orgPredicate(attachments.orgId, orgId))
    .get();
  return row?.value ?? 0;
}
