}

export async function restoreIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);
  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId), "Issue", issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  if (issue.archivedAt === null) throw new RestoreRefusedError("not_archived");

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  const retentionDays = getPlanLimits(org.plan).retentionDays;
  if (Date.now() - new Date(issue.archivedAt).getTime() >= retentionDays * 24 * 60 * 60 * 1000) {
    throw new RestoreRefusedError("expired");
  }
  const project = requireFound(
    await projectRepo.findProjectById(orgId, issue.projectId), "Project", issue.projectId,
  );
  if (project.archivedAt !== null) throw new RestoreRefusedError("project_archived");
  const used = await issueRepo.countIssues(orgId, issue.projectId, { includeArchived: true });
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new RestoreRefusedError("quota");
  }

  const restored = await issueRepo.restoreIssue(orgId, issueId);
  await emit("issue.restored", {
    ...actorEnvelope(actor), issueId: restored.id, projectId: restored.projectId,
  });
  return restored;
}

